<span class="line"><span style="color:#24292E;">      </span><span style="color:#005CC5;">&quot;args&quot;</span><span style="color:#24292E;">: [</span><span style="color:#032F62;">&quot;-y&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;copper3d-mcp&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;--project&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;\${workspaceFolder}&quot;</span><span style="color:#24292E;">]</span></span>
